// SPDX-License-Identifier: MIT
// Prismvault Weigh (Prismheart campaign), plain C++17 for the Unreal binding. A port of
// tools/minigames/prismvault.py (prism-shard-dev), which stays the rules authority. Seeding is CPython-compatible
// (DaedalusPyRandomCore.h, "prismvault:<seed>:<difficulty>"); the RNG picks the hollow shard once at setup.
// Byte parity goes through engines/unreal/core-test/prismvault_parity.txt (prismvault_core_test.cpp), generated by
// tools/minigames/prismvault_parity.py.
#pragma once
#include "DaedalusPyRandomCore.h"
#include <algorithm>
#include <cstdint>
#include <set>
#include <string>
#include <vector>

namespace daedalus { namespace prismvault {

inline const char* GameId() { return "prismvault"; }
inline const char* Title() { return "Prismvault Weigh"; }

struct Difficulty { const char* Name; int Shards; int Weighings; };
inline const Difficulty* Difficulties()
{
	static const Difficulty Table[] = { { "easy", 8, 3 }, { "normal", 12, 3 }, { "hard", 27, 3 } };
	return Table;
}
constexpr int DifficultyCount = 3;
inline const Difficulty* FindDifficulty(const std::string& Name)
{
	for (int I = 0; I < DifficultyCount; ++I) if (Name == Difficulties()[I].Name) return &Difficulties()[I];
	return nullptr;
}

struct Weighing { std::vector<int> Left, Right; char Result; };   // '<' left lighter, '>' right lighter, '=' balanced

struct Game
{
	const Difficulty* Diff = nullptr;
	int Hollow = 0, Weighings = 0;
	std::vector<Weighing> Log;
	std::vector<int> Candidates;
	int Score = 0; bool Over = false, Won = false;
	pyrandom::PyRandom Rng;

	int Shards() const { return Diff ? Diff->Shards : 0; }

	bool Start(std::uint32_t Seed, const std::string& DifficultyName)
	{
		Diff = FindDifficulty(DifficultyName);
		if (!Diff) return false;
		Rng.Seed(std::string(GameId()) + ":" + std::to_string(Seed) + ":" + DifficultyName);
		Score = 0; Over = Won = false;
		Hollow = static_cast<int>(Rng.RandRange(static_cast<std::uint32_t>(Diff->Shards)));
		Weighings = Diff->Weighings; Log.clear();
		Candidates.clear(); for (int I = 0; I < Diff->Shards; ++I) Candidates.push_back(I);
		return true;
	}

	enum class Act : int { Ok = 0, GameOver, NoWeighings, BadGroups, BadShard };

	/** Weigh two equal disjoint groups (sorted, deduplicated as Python does). Result in `Out`. */
	Act Weigh(std::vector<int> Left, std::vector<int> Right, char& Out)
	{
		Out = '?';
		if (Over) return Act::GameOver;
		std::sort(Left.begin(), Left.end()); Left.erase(std::unique(Left.begin(), Left.end()), Left.end());
		std::sort(Right.begin(), Right.end()); Right.erase(std::unique(Right.begin(), Right.end()), Right.end());
		if (Weighings <= 0) return Act::NoWeighings;
		const int N = Shards();
		std::set<int> L(Left.begin(), Left.end()), R(Right.begin(), Right.end());
		bool Disjoint = true; for (int X : Left) if (R.count(X)) Disjoint = false;
		bool InRange = true; for (int X : Left) if (X < 0 || X >= N) InRange = false; for (int X : Right) if (X < 0 || X >= N) InRange = false;
		if (Left.empty() || Left.size() != Right.size() || !Disjoint || !InRange) return Act::BadGroups;
		Out = L.count(Hollow) ? '<' : R.count(Hollow) ? '>' : '=';
		--Weighings;
		Log.push_back({ Left, Right, Out });
		std::vector<int> Keep;
		for (int C : Candidates)
		{
			const bool K = Out == '<' ? L.count(C) != 0 : Out == '>' ? R.count(C) != 0 : (!L.count(C) && !R.count(C));
			if (K) Keep.push_back(C);
		}
		Candidates = Keep;
		return Act::Ok;
	}

	/** Name the hollow shard. `Gained` is 100 + 50 per unused weighing when right; a wrong name loses. */
	Act Name(int Shard, int& Gained)
	{
		Gained = 0;
		if (Over) return Act::GameOver;
		if (Shard < 0 || Shard >= Shards()) return Act::BadShard;
		if (Shard == Hollow) { Gained = 100 + 50 * Weighings; Score += Gained; Over = true; Won = true; }
		else { Over = true; Won = false; }
		return Act::Ok;
	}

	/** prismvault.Game.demo_action: name when one candidate (or no weighings) else split the candidates in thirds. */
	struct Demo { bool IsName; int Shard; std::vector<int> Left, Right; };
	Demo DemoAction() const
	{
		const std::vector<int>& C = Candidates;
		if (C.size() == 1 || Weighings == 0) return { true, C.empty() ? 0 : C.front(), {}, {} };
		const int K = (static_cast<int>(C.size()) + 2) / 3;
		std::vector<int> Left(C.begin(), C.begin() + K), Right(C.begin() + K, C.begin() + std::min<int>(2 * K, static_cast<int>(C.size())));
		if (static_cast<int>(Right.size()) < K)
		{
			const std::set<int> InC(C.begin(), C.end());
			for (int X = 0; X < Shards() && static_cast<int>(Right.size()) < K; ++X) if (!InC.count(X)) Right.push_back(X);
		}
		return { false, -1, Left, Right };
	}

	static std::string ListString(const std::vector<int>& V) { std::string S; for (size_t I = 0; I < V.size(); ++I) { if (I) S.push_back(','); S += std::to_string(V[I]); } return S; }
	std::string CandidatesString() const { return ListString(Candidates); }
};

} } // namespace daedalus::prismvault
